:root {
  /* Tipografía */
  --sec-font-family: "Segoe UI", Arial, sans-serif;
  --sec-number-font: "IBM Plex Mono", Consolas, monospace;

  /* Textos */
  --sec-text-primary: #000000;
  --sec-text-secondary: #000000;

  /* Cuerda */
  --sec-fiber-color: #0A638F;

  /* Cilindros */
  --sec-roller-fill: #D7D8DB;
  --sec-roller-border: #4E4E4E;
  --sec-roller-number: #000000;

  /* Tuberías */
  --sec-steam-color: #930606;
  --sec-condensate-color: #4E4E4E;

  /* Control */
  --sec-control-color: #01524F;

  /* Válvula */
  --sec-valve-color: #0E0E55;

  /* Grosores */
  --sec-fiber-width: 2.8px;
  --sec-roller-border-width: 2.2px;
  --sec-process-width: 1.6px;
  --sec-process-main-width: 2px;
  --sec-control-width: 1.6px;
  --sec-valve-width: 1.4px;

  /* Numeración */
  --sec-roller-number-size: 13px;
}

/* ==========================================================
   ENTORNO TRANSPARENTE
   ========================================================== */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.secador-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--sec-font-family);
  pointer-events: none;
}

.secador-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
}

/* Representación completamente estática */
.secador-widget,
.secador-widget * {
  animation: none !important;
  transition: none !important;
}

/* ==========================================================
   CILINDROS: METAL SATINADO SIN ANILLO INTERIOR
   ========================================================== */

.roller-metal-base {
  stop-color: var(--sec-roller-fill);
}

.roller-body {
  fill: url("#sec2-roller-metal");
  stroke: var(--sec-roller-border);
  stroke-width: var(--sec-roller-border-width);
  filter: url("#sec2-roller-shadow");
}

/* ==========================================================
   CUERDA
   ========================================================== */

.fiber {
  fill: none;
  stroke: var(--sec-fiber-color);
  stroke-width: var(--sec-fiber-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* ==========================================================
   NUMERACIÓN
   ========================================================== */

.roller-label {
  fill: var(--sec-roller-number);
  font-family: var(--sec-number-font);
  font-size: var(--sec-roller-number-size);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

/* ==========================================================
   TUBERÍAS CONTINUAS
   ========================================================== */

.steam-line,
.condensate-line,
.control-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.steam-line {
  stroke: var(--sec-steam-color);
  stroke-width: var(--sec-process-width);
}

.condensate-line {
  stroke: var(--sec-condensate-color);
  stroke-width: var(--sec-process-width);
}

.steam-main,
.condensate-main {
  stroke-width: var(--sec-process-main-width);
}

/*
 * La tubería termina exactamente en el borde de la válvula,
 * sin prolongar el trazo hacia su interior.
 */
.valve-connection {
  stroke-linecap: butt;
}

.steam-node {
  fill: var(--sec-steam-color);
  stroke: var(--sec-steam-color);
  stroke-width: 1px;
}

/* ==========================================================
   CONTROL
   ========================================================== */

.control-line {
  stroke: var(--sec-control-color);
  stroke-width: var(--sec-control-width);
}

.control-node {
  fill: var(--sec-control-color);
  stroke: var(--sec-control-color);
  stroke-width: 1px;
}

/* ==========================================================
   VÁLVULA TRANSPARENTE
   ========================================================== */

.valve-body {
  fill: none;
  stroke: var(--sec-valve-color);
  stroke-width: var(--sec-valve-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.valve-dot {
  fill: var(--sec-valve-color);
  stroke: var(--sec-valve-color);
  stroke-width: 1px;
}

/* Unión horizontal entre la válvula y su actuador */
.valve-link {
  fill: none;
  stroke: var(--sec-valve-color);
  stroke-width: 0.7px;
  stroke-linecap: round;
}

/* ==========================================================
   TEXTOS
   ========================================================== */

.labels text {
  font-family: var(--sec-font-family);
}

.text-steam {
  fill: var(--sec-steam-color);
  font-size: 13px;
  font-weight: 600;
}

.text-condensate {
  fill: var(--sec-condensate-color);
  font-size: 13px;
  font-weight: 600;
}

.text-zone {
  fill: var(--sec-text-primary);
  font-size: 18px;
  font-weight: 600;
  text-anchor: middle;
}

.text-footer {
  fill: var(--sec-text-secondary);
  font-size: 16px;
  font-weight: 500;
  font-style: italic;
}
